-- BIR alphanumeric tax codes (ATCs), from the schedule on BIR Form 2307 (January 2018 ENCS), page 2. Reference data, as printed:
-- section A is expanded withholding, B is business tax withheld by a government or private payor, C by a government payor only.
-- printed_rate is filled only where the form prints a rate; every other rate is set on the tax code by the tax team.
CREATE TABLE bir_atc_codes (
    atc          VARCHAR(5)   PRIMARY KEY CHECK (atc ~ '^[A-Z]{2}[0-9]{3}$'),
    section      CHAR(1)      NOT NULL CHECK (section IN ('A', 'B', 'C')),
    payee_type   VARCHAR(12)  CHECK (payee_type IN ('INDIVIDUAL', 'CORPORATION')),
    description  VARCHAR(500) NOT NULL,
    condition    VARCHAR(200),
    printed_rate NUMERIC(5, 4)
);


-- A code the catalogue does not hold cannot be set on a tax code.
UPDATE tax_codes SET atc = NULL WHERE atc IS NOT NULL AND atc NOT IN (SELECT atc FROM bir_atc_codes);
ALTER TABLE tax_codes ADD CONSTRAINT fk_tax_codes_atc FOREIGN KEY (atc) REFERENCES bir_atc_codes (atc);

-- Whether a supplier is an individual or a corporation decides which ATCs apply to it (WI or WC).
ALTER TABLE suppliers ADD COLUMN payee_type VARCHAR(12) CHECK (payee_type IN ('INDIVIDUAL', 'CORPORATION'));
